# 66_elite_values_table.R
# STATUS: CHAPTER 3 (Political Class) — supporting figure
#
# Table: "British Politicians Out for Themselves, Their Party, or Their Country"
# Data: Jennings, Clarke, Moss & Stoker (2017), Public Opinion Quarterly 81(3): 748-758
# Sources: Gallup (1944, 1972); YouGov n=2,103 (2014, ESRC project ES/L007185/1)
#
# Built as a ggplot figure (not gt) so it saves via ggsave() like all other scripts.
# House style: NAVY header, RED 2014 column, alternating rows, argumentative title.
#
# OUTPUT: figures/ch3_elite_values_table.png

pacman::p_load(tidyverse)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT <- .ROOT
OUT_DIR <- file.path(PROJECT, "figures")

NAVY  <- "#1F3864"
RED   <- "#d7191c"
GREY  <- "#888888"
LGREY <- "#f5f5f5"

# ===========================================================================
# Data (long format for ggplot)
# ===========================================================================

dat <- tribble(
  ~row, ~Response,       ~col, ~year,   ~value,
  1,    "Themselves",    1,    "1944",  "35%",
  1,    "Themselves",    2,    "1972",  "38%",
  1,    "Themselves",    3,    "2014",  "48%",
  2,    "Their party",   1,    "1944",  "22%",
  2,    "Their party",   2,    "1972",  "22%",
  2,    "Their party",   3,    "2014",  "30%",
  3,    "Their country", 1,    "1944",  "36%",
  3,    "Their country", 2,    "1972",  "28%",
  3,    "Their country", 3,    "2014",  "10%",
  4,    "Don't know",    1,    "1944",  "7%",
  4,    "Don't know",    2,    "1972",  "12%",
  4,    "Don't know",    3,    "2014",  "12%"
) |>
  mutate(
    is_2014    = year == "2014",
    is_country = Response == "Their country",
    row_shade  = row %% 2 == 1  # odd rows get LGREY
  )

# Column x positions: response label at x=0, years at x=1,2,3
# Header row at y=5 (above data rows 4..1), title area above that

n_rows   <- 4
header_y <- n_rows + 0.5   # y for column header band
title_y  <- n_rows + 1.2   # y for title text
sub_y    <- n_rows + 0.85  # y for subtitle text

# x positions
x_resp <- 0.5   # centre of response column
x_cols <- c("1944" = 2.1, "1972" = 3.0, "2014" = 3.9)

dat <- dat |>
  mutate(
    x = x_cols[year],
    y = n_rows + 1 - row   # row 1 → y=4, row 4 → y=1
  )

# ===========================================================================
# Build plot
# ===========================================================================

p <- ggplot() +

  # --- Alternating row shading (odd rows) ---
  geom_rect(
    data = dat |> filter(row_shade, col == 1) |> distinct(y),
    aes(xmin = 0, xmax = 4.4, ymin = y - 0.5, ymax = y + 0.5),
    fill = LGREY, colour = NA
  ) +

  # --- "Their country" row border lines ---
  geom_segment(
    data = dat |> filter(is_country, col == 1) |> distinct(y),
    aes(x = 0, xend = 4.4, y = y + 0.5, yend = y + 0.5),
    colour = NAVY, linewidth = 0.5
  ) +
  geom_segment(
    data = dat |> filter(is_country, col == 1) |> distinct(y),
    aes(x = 0, xend = 4.4, y = y - 0.5, yend = y - 0.5),
    colour = NAVY, linewidth = 0.5
  ) +

  # --- Outer table borders (top and bottom) ---
  geom_segment(aes(x = 0, xend = 4.4, y = 0.5,           yend = 0.5),
               colour = NAVY, linewidth = 0.8) +
  geom_segment(aes(x = 0, xend = 4.4, y = n_rows + 0.5,  yend = n_rows + 0.5),
               colour = NAVY, linewidth = 0.8) +

  # --- Header band ---
  geom_rect(
    aes(xmin = 0, xmax = 4.4, ymin = header_y - 0.35, ymax = header_y + 0.35),
    fill = NAVY, colour = NA
  ) +
  # Header border below
  geom_segment(aes(x = 0, xend = 4.4,
                   y = header_y - 0.35, yend = header_y - 0.35),
               colour = NAVY, linewidth = 0.6) +

  # --- Header labels ---
  geom_text(aes(x = x_resp, y = header_y, label = ""),
            colour = "white", fontface = "bold", size = 3.8, hjust = 0.5) +
  geom_text(data = tibble(year = c("1944","1972"), x = x_cols[c("1944","1972")]),
            aes(x = x, y = header_y, label = year),
            colour = "white", fontface = "bold", size = 3.8) +
  geom_text(aes(x = x_cols["2014"], y = header_y, label = "2014"),
            colour = RED, fontface = "bold", size = 3.8) +

  # --- Response labels ---
  geom_text(
    data = dat |> distinct(row, Response, y, is_country),
    aes(x = x_resp, y = y, label = Response,
        fontface = if_else(is_country, "bold", "bold")),
    colour = NAVY, size = 3.5, hjust = 0.5
  ) +

  # --- Data values: 1944 and 1972 ---
  geom_text(
    data = dat |> filter(!is_2014),
    aes(x = x, y = y, label = value,
        fontface = if_else(is_country, "bold", "plain")),
    colour = "grey30", size = 3.5
  ) +

  # --- Data values: 2014 (RED bold) ---
  geom_text(
    data = dat |> filter(is_2014),
    aes(x = x, y = y, label = value),
    colour = RED, fontface = "bold", size = 3.8
  ) +

  # --- Title ---
  annotate("text",
           x = 2.2, y = title_y + 0.55,
           label = "Belief that politicians serve their country has collapsed",
           colour = NAVY, fontface = "bold", size = 4.0, hjust = 0.5) +

  # --- Subtitle ---
  annotate("text",
           x = 2.2, y = title_y + 0.18,
           label = "% saying British politicians are in politics for themselves, their party, or their country",
           colour = GREY, size = 2.9, hjust = 0.5) +

  # --- Source note ---
  annotate("text",
           x = 0.05, y = 0.18,
           label = paste0(
             "Source: Jennings, Clarke, Moss & Stoker (2017), Public Opinion Quarterly 81(3): 748\u2013758. ",
             "Data: Gallup (1944, 1972); YouGov n=2,103 (2014).\n",
             "Question: \u2018Do you think that British politicians are out merely for themselves, ",
             "for their party, or to do their best for their country?\u2019"
           ),
           colour = GREY, size = 2.2, hjust = 0, vjust = 1, lineheight = 1.2) +

  # --- Scales and theme ---
  scale_x_continuous(limits = c(0, 4.4), expand = c(0, 0)) +
  scale_y_continuous(limits = c(0, title_y + 0.9), expand = c(0, 0)) +
  theme_void() +
  theme(
    plot.margin     = margin(8, 8, 8, 8),
    plot.background = element_rect(fill = "white", colour = NA)
  )

# ===========================================================================
# Save
# ===========================================================================

out_path <- file.path(OUT_DIR, "ch3_elite_values_table.png")
ggsave(out_path, p, width = 6, height = 3.8, dpi = 300)
cat("Table saved:", out_path, "\n")
